import{_ as t,o as r,c as l,a5 as a}from"./chunks/framework.a5no_H3L.js";const m=JSON.parse('{"title":"常用错误码速查","description":"本页只提供首查方向。错误文本、SQLSTATE 和触发条件可能随版本、客户端和会话模式变化；继续排查连接、锁或查询问题时见常见问题与避坑指南。","frontmatter":{},"headers":[],"relativePath":"mysql/reference/errors.md","filePath":"mysql/reference/errors.md"}'),d={name:"mysql/reference/errors.md"};function s(n,e,c,i,o,f){return r(),l("div",null,[...e[0]||(e[0]=[a('<h1 id="常用错误码速查" tabindex="-1" data-src-line="1" data-src-file="mysql/reference/errors.md">常用错误码速查 <a class="header-anchor" href="#常用错误码速查" aria-label="Permalink to &quot;常用错误码速查&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="mysql/reference/errors.md"><p data-src-line="3" data-src-file="mysql/reference/errors.md">本页只提供首查方向。错误文本、SQLSTATE 和触发条件可能随版本、客户端和会话模式变化；继续排查连接、锁或查询问题时见<a href="./../10-practice/chapter-04-common-issues.html">常见问题与避坑指南</a>。</p></blockquote><h2 id="连接与权限" tabindex="-1" data-src-line="5" data-src-file="mysql/reference/errors.md">连接与权限 <a class="header-anchor" href="#连接与权限" aria-label="Permalink to &quot;连接与权限&quot;">​</a></h2><table tabindex="0"><thead data-src-line="7" data-src-file="mysql/reference/errors.md"><tr data-src-line="7" data-src-file="mysql/reference/errors.md"><th style="text-align:left;">错误码</th><th style="text-align:left;">典型信息</th><th style="text-align:left;">首查方向</th></tr></thead><tbody data-src-line="9" data-src-file="mysql/reference/errors.md"><tr data-src-line="9" data-src-file="mysql/reference/errors.md"><td style="text-align:left;">1040</td><td style="text-align:left;">Too many connections</td><td style="text-align:left;">比较 <code>max_connections</code>、<code>Threads_connected</code>、<code>Max_used_connections</code> 和应用连接池总峰值，先排除泄漏</td></tr><tr data-src-line="10" data-src-file="mysql/reference/errors.md"><td style="text-align:left;">1045</td><td style="text-align:left;">Access denied for user</td><td style="text-align:left;">核对用户名、来源主机、密码、认证插件和 <code>SHOW GRANTS</code>；不能仅凭错误码判断是密码还是权限问题</td></tr><tr data-src-line="11" data-src-file="mysql/reference/errors.md"><td style="text-align:left;">2003</td><td style="text-align:left;">Can&#39;t connect to MySQL server</td><td style="text-align:left;">检查服务状态、监听地址、端口、DNS、防火墙和 TLS 配置</td></tr><tr data-src-line="12" data-src-file="mysql/reference/errors.md"><td style="text-align:left;">2006</td><td style="text-align:left;">MySQL server has gone away</td><td style="text-align:left;">这是客户端侧连接已断开；检查服务端错误日志、网络/负载均衡、空闲超时、查询超长和数据包大小</td></tr><tr data-src-line="13" data-src-file="mysql/reference/errors.md"><td style="text-align:left;">2013</td><td style="text-align:left;">Lost connection during query</td><td style="text-align:left;">检查服务端是否终止连接、网络抖动、超时配置和导致会话中断的长语句</td></tr></tbody></table><p data-src-line="15" data-src-file="mysql/reference/errors.md">客户端错误码 2006、2013 不是由服务端错误码表单独决定。先保存客户端完整异常和服务端同一时间点日志，再调整 <code>wait_timeout</code>、<code>net_read_timeout</code> 或 <code>max_allowed_packet</code> 等参数。</p><h2 id="sql-与数据" tabindex="-1" data-src-line="17" data-src-file="mysql/reference/errors.md">SQL 与数据 <a class="header-anchor" href="#sql-与数据" aria-label="Permalink to &quot;SQL 与数据&quot;">​</a></h2><table tabindex="0"><thead data-src-line="19" data-src-file="mysql/reference/errors.md"><tr data-src-line="19" data-src-file="mysql/reference/errors.md"><th style="text-align:left;">错误码</th><th style="text-align:left;">典型信息</th><th style="text-align:left;">首查方向</th></tr></thead><tbody data-src-line="21" data-src-file="mysql/reference/errors.md"><tr data-src-line="21" data-src-file="mysql/reference/errors.md"><td style="text-align:left;">1062</td><td style="text-align:left;">Duplicate entry for key</td><td style="text-align:left;">读取完整索引名和重复值；比较并发写入与幂等键。只有业务确实允许覆盖时才选择 <code>ON DUPLICATE KEY UPDATE</code>，不要用 <code>INSERT IGNORE</code> 掩盖数据问题</td></tr><tr data-src-line="22" data-src-file="mysql/reference/errors.md"><td style="text-align:left;">1064</td><td style="text-align:left;">SQL syntax or not exist error</td><td style="text-align:left;">按错误位置检查语法、引号、保留字、<code>sql_mode</code> 和生成 SQL 的客户端版本</td></tr><tr data-src-line="23" data-src-file="mysql/reference/errors.md"><td style="text-align:left;">1146</td><td style="text-align:left;">Table doesn&#39;t exist</td><td style="text-align:left;">核对当前默认数据库、schema、对象大小写和权限</td></tr><tr data-src-line="24" data-src-file="mysql/reference/errors.md"><td style="text-align:left;">1213</td><td style="text-align:left;">Deadlock found when trying to get lock</td><td style="text-align:left;">查看 <code>SHOW ENGINE INNODB STATUS</code> 的最新死锁，比较事务顺序和扫描范围</td></tr><tr data-src-line="25" data-src-file="mysql/reference/errors.md"><td style="text-align:left;">1205</td><td style="text-align:left;">Lock wait timeout exceeded</td><td style="text-align:left;">查看持锁事务、锁图和长事务；提高超时只会延迟失败，不解决阻塞</td></tr><tr data-src-line="26" data-src-file="mysql/reference/errors.md"><td style="text-align:left;">1292</td><td style="text-align:left;">Truncated incorrect value</td><td style="text-align:left;">检查目标列类型、日期格式和严格模式；非严格模式可能降级为警告并写入不同值</td></tr><tr data-src-line="27" data-src-file="mysql/reference/errors.md"><td style="text-align:left;">1366</td><td style="text-align:left;">Incorrect string value</td><td style="text-align:left;">同时核对连接字符集、列字符集、无效字节和客户端编码</td></tr><tr data-src-line="28" data-src-file="mysql/reference/errors.md"><td style="text-align:left;">1452</td><td style="text-align:left;">Foreign key constraint fails</td><td style="text-align:left;">检查父记录、外键值、字段类型/排序规则和插入、删除顺序</td></tr></tbody></table><h2 id="存储与结构" tabindex="-1" data-src-line="30" data-src-file="mysql/reference/errors.md">存储与结构 <a class="header-anchor" href="#存储与结构" aria-label="Permalink to &quot;存储与结构&quot;">​</a></h2><table tabindex="0"><thead data-src-line="32" data-src-file="mysql/reference/errors.md"><tr data-src-line="32" data-src-file="mysql/reference/errors.md"><th style="text-align:left;">错误码</th><th style="text-align:left;">典型信息</th><th style="text-align:left;">首查方向</th></tr></thead><tbody data-src-line="34" data-src-file="mysql/reference/errors.md"><tr data-src-line="34" data-src-file="mysql/reference/errors.md"><td style="text-align:left;">1114</td><td style="text-align:left;">Table is full</td><td style="text-align:left;">检查文件系统空间、表空间容量、存储引擎上限以及 MEMORY 表的内存配置；不能只改一个数据文件参数</td></tr><tr data-src-line="35" data-src-file="mysql/reference/errors.md"><td style="text-align:left;">3140</td><td style="text-align:left;">Invalid JSON text</td><td style="text-align:left;">检查 JSON 字符串的引号、转义、编码和函数返回值</td></tr></tbody></table><p data-src-line="37" data-src-file="mysql/reference/errors.md">处理原则是先恢复业务或隔离故障，再保留现场并定位根因。调大超时、删除冲突、关闭约束或切换 SQL Mode 都可能改变业务语义，必须写入变更记录并验证回滚条件。</p>',10)])])}const x=t(d,[["render",s]]);export{m as __pageData,x as default};
